(6354160, 940630, 124256, '<td valign="top">I would have liked this one a lot more if it didn''t seem so washed out.  Seems like more contrast would have helped.</td>', 'I would have liked this one a lot more if it didn''t seem so washed out.  Seems like more contrast would have helped.', '2011-03-17 02:05:31.000000', NULL, 1),
(6354161, 940709, 124256, '<td valign="top">Wow, how did you capture that look!  Awesome.</td>', 'Wow, how did you capture that look!  Awesome.', '2011-03-17 02:06:51.000000', NULL, 1),
(6354163, 940363, 96751, '<td valign="top">The composition and lighting are really nice, and I think you''ve captured the eyes just fine.  For me, it lacks a bit of drama.</td>', 'The composition and lighting are really nice, and I think you''ve captured the eyes just fine.  For me, it lacks a bit of drama.', '2011-03-17 02:14:31.000000', NULL, 1),
(6354164, 940556, 96751, '<td valign="top">Lovely, but the lighting is much to generalized to create a Librodo look.</td>', 'Lovely, but the lighting is much to generalized to create a Librodo look.', '2011-03-17 02:14:56.000000', NULL, 1),
(6354165, 940778, 96751, '<td valign="top">Yaaay.  Another male model.  Thought I was the only one.  Nicely done, although the eyes might have used just a bit more brightening.  It might be a bit colorless for a Librodo, but it''s a very strong image.</td>', 'Yaaay.  Another male model.  Thought I was the only one.  Nicely done, although the eyes might have used just a bit more brightening.  It might be a bit colorless for a Librodo, but it''s a very strong image.', '2011-03-17 02:15:58.000000', NULL, 1),
(6354166, 940922, 96751, '<td valign="top">I find the props distracting from the model.</td>', 'I find the props distracting from the model.', '2011-03-17 02:16:28.000000', NULL, 1),
(6354167, 940161, 96751, '<td valign="top">Truly lovely.  Very nicely composed and edited.  Strong colors and piercing eyes.  The closest to "librodo style" I''ve seen yet.</td>', 'Truly lovely.  Very nicely composed and edited.  Strong colors and piercing eyes.  The closest to "librodo style" I''ve seen yet.', '2011-03-17 02:17:05.000000', NULL, 1),
(6354168, 940401, 96751, '<td valign="top">Exceptional entry.  Love the hyper-realism, the bold, dramatic light, and the connection this model has with the viewer.</td>', 'Exceptional entry.  Love the hyper-realism, the bold, dramatic light, and the connection this model has with the viewer.', '2011-03-17 02:17:42.000000', NULL, 1),
(6354170, 940934, 96751, '<td valign="top">Best in show :-)  Adorable parody.</td>', 'Best in show :-)  Adorable parody.', '2011-03-17 02:19:08.000000', NULL, 1),
(6354171, 940378, 96751, '<td valign="top">Very nicely done.</td>', 'Very nicely done.', '2011-03-17 02:19:21.000000', NULL, 1),
