(6359850, 939912, 124815, '<td valign="top">"A picture is worth a thousand words".  One would like to write the thousand words book inspired by this portrait. 10</td>', '"A picture is worth a thousand words".  One would like to write the thousand words book inspired by this portrait. 10', '2011-03-22 10:16:29.000000', NULL, 1),
(6359851, 940739, 124815, '<td valign="top">The light is mesmerizing.</td>', 'The light is mesmerizing.', '2011-03-22 10:16:33.000000', NULL, 1),
