(6359858, 940723, 124815, '<td valign="top">It sure helps to be in an exotic place and work of "a la maniere" de Librodo. Very, very well done.</td>', 'It sure helps to be in an exotic place and work of "a la maniere" de Librodo. Very, very well done.', '2011-03-22 10:17:02.000000', NULL, 1),
(6359859, 939860, 124815, '<td valign="top">Brrr. One look and he scanned everything. Great tonality. Border makes perfect sense and the lighting at the top is worth all the gold on his fingers.</td>', 'Brrr. One look and he scanned everything. Great tonality. Border makes perfect sense and the lighting at the top is worth all the gold on his fingers.', '2011-03-22 10:17:07.000000', NULL, 1),
